// Игрушечные векторы (иллюстрация), арифметика настоящая
const dot = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0);
const softmax = xs => {
  const e = xs.map(x => Math.exp(x - Math.max(...xs)));
  const sum = e.reduce((a, b) => a + b);
  return e.map(x => x / sum);
};

const tokens = ["кот", "сел", "ковёр", "он"];
const K = [[1, 0], [0, 0], [0, 1], [0.5, 0]]; // бирки: ось 1 = «живое существо», ось 2 = «предмет»
const V = [[1, 0, 0], [0, 1, 0], [0, 0, 1], [0, 0, 0]]; // что каждый токен передаёт
const q = [4, 0]; // запрос токена «он»: ищу живое существо

const scores = K.map(k => dot(q, k) / Math.sqrt(q.length));
const w = softmax(scores);
const out = [0, 1, 2].map(j => w.reduce((s, wi, i) => s + wi * V[i][j], 0));
const r = x => +x.toFixed(2); // round for printing

console.log(scores.map(r)); // [2.83, 0, 0, 1.41]
console.log(w.map(r));      // [0.73, 0.04, 0.04, 0.18]
console.log(out.map(r));    // [0.73, 0.04, 0.04]  ← в «он» перетекло в основном содержимое «кот»

import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic(); // reads ANTHROPIC_API_KEY
declare const bookText: string;  // the long, unchanging document

async function ask(question: string) {
  const res = await client.messages.create({
    model: "claude-sonnet-5",
    max_tokens: 1024,
    system: [
      { type: "text", text: "Answer only from the book below." },
      {
        type: "text",
        text: bookText,
        cache_control: { type: "ephemeral" }, // breakpoint: cache everything up to here
      },
    ],
    messages: [{ role: "user", content: question }], // changes every time, after the breakpoint
  });
  const u = res.usage;
  console.log(u.cache_creation_input_tokens, u.cache_read_input_tokens, u.input_tokens);
}

ask("Who is the narrator?");
